function renderChart(){const r=resize(chart,cc),pad=27,w=r.width-pad-8,h=r.height-34;cc.clearRect(0,0,r.width,r.height);const sets=[model.history,...(baseline?[baseline.history]:[])],values=sets.flatMap(a=>a.map(p=>p.mean)),min=Math.floor(Math.min(...values)-.5),max=Math.max(min+2,Math.ceil(Math.max(...values)+.5)),end=Math.max(60,model.time);cc.font='8px monospace';for(let i=0;i<=3;i++){const y=8+h*i/3;cc.strokeStyle='#364437';cc.lineWidth=.5;cc.beginPath();cc.moveTo(pad,y);cc.lineTo(r.width-5,y);cc.stroke();cc.fillStyle='#8fa086';cc.fillText(fmt(max-(max-min)*i/3,0)+'°',0,y+3);}sets.forEach((a,i)=>{cc.strokeStyle=i?'#88b7e1':'#c6ef85';cc.lineWidth=1.8;cc.setLineDash(i?[4,3]:[]);cc.beginPath();a.forEach((p,j)=>{const x=pad+p.time/end*w,y=8+(max-p.mean)/(max-min)*h;j?cc.lineTo(x,y):cc.moveTo(x,y);});const st=(i?baseline:model).stats();cc.lineTo(pad+model.time/end*w,8+(max-st.mean)/(max-min)*h);cc.stroke();});cc.setLineDash([]);cc.fillStyle='#8fa086';cc.fillText('0',pad,r.height-5);cc.fillText(fmt(end/60,1)+' min',r.width-45,r.height-5);}
